INSERT INTO `t_report_template` VALUES (1,'佛山市南海区石实实验学校','{\"coin\": {\"compare\": {\"max\": 700, \"step\": 100}, \"incomeTop\": {\"max\": 180, \"step\": 30}, \"expenseTop\": {\"max\": 30, \"step\": 5}, \"incomeLeast\": {\"max\": 3, \"step\": 0.5}, \"weeklyIncome\": {\"max\": 100, \"step\": 20}, \"weeklyExpense\": {\"max\": 30, \"step\": 10}}, \"intro\": \"石实实验学校（原石门实验学校）创办于1999年，是佛山市第一所实验类全寄宿学校，2019年迁入南海区大沥镇太平新校区。学校秉持“扬长教育、出彩人生”的办学理念，以“人人出彩”为追求，办学成果丰硕，累计培育数十名清华、北大学子，被誉为佛山民办教育的标杆。\", \"radar\": {\"max\": 180, \"motto\": \"士不可以不弘毅，任重而道远。\", \"mottoNote\": \"译文：读书人不可不志向远大、意志坚强，因为他肩负重任，路途遥远。\", \"mottoSource\": \"——《论语·泰伯》，校训源出于此\"}, \"philosophy\": [[\"校训\", \"任重道远，毋忘奋斗\"], [\"办学理念\", \"扬长教育，出彩人生\"], [\"育人追求\", \"人人出彩，各美其美\"], [\"共同价值观\", \"以爱治校，尊重你我\"], [\"石门精神\", \"科学，协作，拼搏\"], [\"办学使命\", \"为每一位学生的终身发展提供最适合的教育\"]], \"nineGridIntro\": \"“扬长教育”是我校的育人特色：发现每一位学生的长处，让长处更长、亮点更亮。品德铸魂，行为立范，身心砺志，劳动立勤，学业启思，创新促悟，艺术润美，特长扬长，体育强健。五育并举，扬长出彩，如同九色光谱，照亮每个孩子独一无二的出彩人生。\"}','启用','2026-08-24 10:12:48','2026-08-24 10:12:48');
/*!40000 ALTER TABLE `t_report_template` ENABLE KEYS */;
UNLOCK TABLES;

