DROP TABLE IF EXISTS `t_evaluation`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_evaluation` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `student_id` bigint NOT NULL,
  `teacher_id` bigint DEFAULT NULL,
  `indicator_id` bigint NOT NULL,
  `title` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '记录卡标题（尊师守纪/作业优秀(地生)…）',
  `score` decimal(10,2) NOT NULL,
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `eval_time` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_student_time` (`student_id`,`eval_time`),
  KEY `idx_indicator` (`indicator_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3797 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='评价记录';
